import os
from openai import OpenAI

client = OpenAI(api_key=os.getenv("OPENAI_API_KEY"))

def extract_receipt_data(image_path):
    with open(image_path, "rb") as image_file:
        response = client.chat.completions.create(
            model="gpt-4-vision-preview",
            messages=[
                {
                    "role": "user",
                    "content": [
                        {"type": "text", "text": "Extract merchant name, tax amount, total amount, and items (list of dictionaries with name, quantity, price) from this receipt. Return as JSON."},
                        {"type": "image_url", "image_url": {"url": f"data:image/jpeg;base64,{image_file.read().hex()}"}}
                    ]
                }
            ],
            max_tokens=500
        )
    import json
    return json.loads(response.choices[0].message.content)
